import type { ICalendarPlusSettings } from './types';

// Fetch Calendar+ settings.
export async function fetchSettings() {
	try {
		if (typeof window.calendarPlusSettings !== 'undefined') {
			const { apiUrl, nonce } = window.calendarPlusSettings;

			const response = await fetch(apiUrl, {
				headers: {
					'X-WP-Nonce': nonce,
				},
			});
			if (!response.ok) {
				throw new Error('Failed to fetch settings');
			}
			return await response.json();
		}
	} catch (error) {
		console.error('Error fetching settings:', error);
		return {};
	}
}

// Save Calendar+ settings.
export async function saveSettings(settings: ICalendarPlusSettings) {
	try {
		const { apiUrl, nonce } = window.calendarPlusSettings;

		const response = await fetch(apiUrl, {
			method: 'POST',
			headers: {
				'Content-Type': 'application/json',
				'X-WP-Nonce': nonce,
			},
			body: JSON.stringify(settings),
		});
		if (!response.ok) {
			const errorText = await response.text();
			console.error(` Status: ${response.status}, Message: ${errorText}`);
			return {
				success: false,
				message: `Failed to save settings.`,
			};
		}
		const result = await response.json();
		return { success: true, data: result };
	} catch (error) {
		console.error(`error: ${error.message}`);
		return { success: false, message: error.message || 'An unknown error occurred while saving settings.' };
	}
}
